<div class="welcome-row"><div><div class="form-kicker">IMPORTAÇÃO DE EXTRATOS</div><h1>Importar movimentações</h1><p class="page-subtitle">Pré-visualize OFX ou CSV e selecione o que deve entrar na conta.</p></div></div>
<?php if($errors): ?><div class="alert error"><?=e(implode(' ',$errors))?></div><?php endif; ?><?php if($notice): ?><div class="alert success"><?=e($notice)?></div><?php endif; ?>
<section class="panel editor-panel"><div class="panel-head"><div><h3>Enviar arquivo</h3><p>Arquivos são processados na memória e não ficam armazenados no servidor. Máximo de 3 MB e 500 lançamentos.</p></div></div><form method="post" action="/imports/upload" enctype="multipart/form-data" class="import-upload"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Conta de destino<select name="account_id" required><?php foreach($accounts as $account): ?><option value="<?=(int)$account['id']?>"><?php echo e($account['name']); ?></option><?php endforeach; ?></select></label><label>Arquivo OFX ou CSV<input type="file" name="statement" accept=".ofx,.csv,text/csv,application/x-ofx" required></label><button class="button primary">Carregar prévia</button></form></section>
<?php if($stage&&$stage['stage']==='map'): ?><section class="panel editor-panel"><div class="panel-head"><div><h3>Mapear colunas</h3><p>Escolha quais colunas correspondem à data, descrição, valor e tipo.</p></div></div><form method="post" action="/imports/prepare" class="data-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><?php foreach(['date'=>'Data','description'=>'Descrição','amount'=>'Valor','type'=>'Tipo (opcional)'] as $key=>$label): ?><label><?=e($label)?><select name="<?=$key?>" <?=$key!=='type'?'required':''?>><option value="">Não usar</option><?php foreach($stage['headers'] as $index=>$header): ?><option value="<?=$index?>" <?=($key==='date'&&preg_match('/data|date/i',$header))||($key==='description'&&preg_match('/descr|memo|name|histórico/i',$header))||($key==='amount'&&preg_match('/valor|amount|value/i',$header))||($key==='type'&&preg_match('/tipo|type|natureza/i',$header))?'selected':''?>><?=e($header)?></option><?php endforeach; ?></select></label><?php endforeach; ?><div class="form-actions"><button class="button primary">Gerar prévia</button></div></form></section><?php endif; ?>
<?php if($stage&&$stage['stage']==='preview'): $accountName='Conta selecionada';foreach($accounts as $account)if((int)$account['id']===(int)$stage['account'])$accountName=$account['name'];$duplicates=count(array_filter($stage['rows'],fn($row)=>$row['duplicate'])); ?><section class="panel import-preview"><div class="panel-head"><div><h3>Prévia da importação</h3><p><?=count($stage['rows'])?> linha(s) · <?=e($accountName)?> · <?=$duplicates?> possível(is) duplicidade(s)</p></div><form method="post" action="/imports/discard"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><button>Descartar prévia</button></form></div><form method="post" action="/imports/confirm"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><div class="table-wrap"><table><thead><tr><th>Importar</th><th>Data</th><th>Tipo</th><th>Descrição</th><th class="right">Valor</th><th>Situação</th></tr></thead><tbody><?php foreach($stage['rows'] as $i=>$row): ?><tr><td><input type="checkbox" name="row[]" value="<?=$i?>" <?=$row['duplicate']?'disabled':'checked'?>></td><td><?=e(date('d/m/Y',strtotime($row['date'])))?></td><td><?=$row['type']==='income'?'Receita':'Despesa'?></td><td><?=e($row['description'])?></td><td class="right"><?=money((int)$row['amount'])?></td><td><?=$row['duplicate']?'<span class="status-pill pending">Possível duplicidade</span>':'Nova'?></td></tr><?php endforeach; ?></tbody></table></div><div class="form-actions"><button class="button primary">Confirmar lançamentos selecionados</button></div></form></section><?php endif; ?>
